lxml._elementpath.find:
def find(elem, path, namespaces=None):
    it = iterfind(elem, path, namespaces)
    try:
        return next(it)
    except StopIteration:
        return None

lxml.html.__init__._element_name:
def _element_name(el):
    if isinstance(el, etree.CommentBase):
        return 'comment'
    elif isinstance(el, basestring):
        return 'string'
    else:
        return _nons(el.tag)

lxml.ElementInclude.default_loader:
def default_loader(href, parse, encoding=None):
    file = open(href, 'rb')
    if parse == 'xml':
        data = etree.parse(file).getroot()
    else:
        data = file.read()
        if not encoding:
            encoding = 'utf-8'
        data = data.decode(encoding)
    file.close()
    return data

lxml.html.html5parser._looks_like_url:
def _looks_like_url(str):
    scheme = urlparse(str)[0]
    if not scheme:
        return False
    elif (sys.platform == 'win32' and scheme in string.ascii_letters and len(scheme) == 1):
        return False
    else:
        return True

lxml._elementpath.prepare_predicate:
def prepare_predicate(next, token):
    signature = ''
    predicate = []
    while 1:
        token = next()
        if token[0] == ']':
            break
        if token == ('', ''):
            continue
        if (token[0] and token[0][:1] in '\'"'):
            token = ("'", token[0][1:-1])
        signature += (token[0] or '-')
        predicate.append(token[1])
    if signature == '@-':
        key = predicate[1]

        def select(result):
            for elem in result:
                if elem.get(key) is not None:
                    yield elem
        return select
    if signature == "@-='":
        key = predicate[1]
        value = predicate[-1]

        def select(result):
            for elem in result:
                if elem.get(key) == value:
                    yield elem
        return select
    if (signature == '-' and not re.match('-?\\d+$', predicate[0])):
        tag = predicate[0]

        def select(result):
            for elem in result:
                for _ in elem.iterchildren(tag):
                    yield elem
                    break
        return select
    if (signature == ".='" or (signature == "-='" and not re.match('-?\\d+$', predicate[0]))):
        tag = predicate[0]
        value = predicate[-1]
        if tag:

            def select(result):
                for elem in result:
                    for e in elem.iterchildren(tag):
                        if ''.join(e.itertext()) == value:
                            yield elem
                            break
        else:

            def select(result):
                for elem in result:
                    if ''.join(elem.itertext()) == value:
                        yield elem
        return select
    if (signature == '-' or signature == '-()' or signature == '-()-'):
        if signature == '-':
            index = int(predicate[0]) - 1
            if index < 0:
                if index == -1:
                    raise SyntaxError('indices in path predicates are 1-based, not 0-based')
                else:
                    raise SyntaxError('path index >= 1 expected')
        else:
            if predicate[0] != 'last':
                raise SyntaxError('unsupported function')
            if signature == '-()-':
                try:
                    index = int(predicate[2]) - 1
                except ValueError:
                    raise SyntaxError('unsupported expression')
            else:
                index = -1

        def select(result):
            for elem in result:
                parent = elem.getparent()
                if parent is None:
                    continue
                try:
                    elems = list(parent.iterchildren(elem.tag))
                    if elems[index] is elem:
                        yield elem
                except IndexError:
                    pass
        return select
    raise SyntaxError('invalid predicate')

lxml.html.diff.merge_insert:
def merge_insert(ins_chunks, doc):
    """ doc is the already-handled document (as a list of text chunks);
    here we add <ins>ins_chunks</ins> to the end of that.  """
    (unbalanced_start, balanced, unbalanced_end) = split_unbalanced(ins_chunks)
    doc.extend(unbalanced_start)
    if (doc and not doc[-1].endswith(' ')):
        doc[-1] += ' '
    doc.append('<ins>')
    if (balanced and balanced[-1].endswith(' ')):
        balanced[-1] = balanced[-1][:-1]
    doc.extend(balanced)
    doc.append('</ins> ')
    doc.extend(unbalanced_end)

lxml.html.diff.serialize_html_fragment:
def serialize_html_fragment(el, skip_outer=False):
    """ Serialize a single lxml element as HTML.  The serialized form
    includes the elements tail.  

    If skip_outer is true, then don't serialize the outermost tag
    """
    assert not isinstance(el, basestring), 'You should pass in an element, not a string like %r' % el
    html = etree.tostring(el, method='html', encoding=_unicode)
    if skip_outer:
        html = html[html.find('>') + 1:]
        html = html[:html.rfind('<')]
        return html.strip()
    else:
        return html

lxml._elementpath.prepare_parent:
def prepare_parent(next, token):

    def select(result):
        for elem in result:
            parent = elem.getparent()
            if parent is not None:
                yield parent
    return select

lxml._elementpath.prepare_descendant:
def prepare_descendant(next, token):
    token = next()
    if token[0] == '*':
        tag = '*'
    elif not token[0]:
        tag = token[1]
    else:
        raise SyntaxError('invalid descendant')

    def select(result):
        for elem in result:
            for e in elem.iterdescendants(tag):
                yield e
    return select
